    77  template<typename TableType>
    78  static bool
    79  _subset (hb_subset_plan_t *plan)
    80  {
    81    hb_blob_t *source_blob = hb_sanitize_context_t ().reference_table<TableType> (plan->source);
    82    const TableType *table = source_blob->as<TableType> ();
    83
    84    hb_tag_t tag = TableType::tableTag;
    85    hb_bool_t result = false;
    86    if (source_blob->data)
    87    {
    88      result = table->subset(plan);
    89    } else {
    90      DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset sanitize failed on source table.", HB_UNTAG(tag));
    91    }
    92
    93    hb_blob_destroy (source_blob);
    94    DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset %s", HB_UNTAG(tag), result ? "success" : "FAILED!");
    95    return result;
    96  }
