   173  /**
   174   * hb_subset_plan_destroy:
   175   *
   176   * Since: 1.7.5
   177   **/
   178  void
   179  hb_subset_plan_destroy (hb_subset_plan_t *plan)
   180  {
   181    if (!hb_object_destroy (plan)) return;
   182
   183    hb_set_destroy (plan->unicodes);
   184    plan->glyphs.fini();
   185    hb_face_destroy (plan->source);
   186    hb_face_destroy (plan->dest);
   187    hb_map_destroy (plan->codepoint_to_glyph);
   188    hb_map_destroy (plan->glyph_map);
   189
   190    free (plan);
   191  }
