    37  struct hb_subset_plan_t
    38  {
    39    hb_object_header_t header;
    40    ASSERT_POD ();
    41
    42    hb_bool_t drop_hints;
    43    hb_bool_t drop_ot_layout;
    44
    45    // For each cp that we'd like to retain maps to the corresponding gid.
    46    hb_set_t *unicodes;
    47
    48    // This list contains the complete set of glyphs to retain and may contain
    49    // more glyphs then the lists above.
    50    hb_vector_t<hb_codepoint_t> glyphs;
    51
    52    hb_map_t *codepoint_to_glyph;
    53    hb_map_t *glyph_map;
    54
    55    // Plan is only good for a specific source/dest so keep them with it
    56    hb_face_t *source;
    57    hb_face_t *dest;
    58
    59    inline hb_bool_t
    60    new_gid_for_codepoint (hb_codepoint_t codepoint,
    61                           hb_codepoint_t *new_gid) const
    62    {
    63      hb_codepoint_t old_gid = codepoint_to_glyph->get (codepoint);
    64      if (old_gid == HB_MAP_VALUE_INVALID)
    65        return false;
    66
    67      return new_gid_for_old_gid (old_gid, new_gid);
    68    }
    69
    70    inline hb_bool_t
    71    new_gid_for_old_gid (hb_codepoint_t old_gid,
    72                        hb_codepoint_t *new_gid) const
    73    {
    74      hb_codepoint_t gid = glyph_map->get (old_gid);
    75      if (gid == HB_MAP_VALUE_INVALID)
    76        return false;
    77
    78      *new_gid = gid;
    79      return true;
    80    }
    81
    82    inline hb_bool_t
    83    add_table (hb_tag_t tag,
    84               hb_blob_t *contents)
    85    {
    86      hb_blob_t *source_blob = source->reference_table (tag);
    87      DEBUG_MSG(SUBSET, nullptr, "add table %c%c%c%c, dest %d bytes, source %d bytes",
    88                HB_UNTAG(tag),
    89                hb_blob_get_length (contents),
    90                hb_blob_get_length (source_blob));
    91      hb_blob_destroy (source_blob);
    92      return hb_face_builder_add_table (dest, tag, contents);
    93    }
    94  };
